// apiKeyAlphabet is the set of characters in an API key's random part.
const apiKeyAlphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

// newAPIKeyToken returns "tly_" followed by 40 random characters from apiKeyAlphabet.
func newAPIKeyToken() string {
	const n = 40
	out := make([]byte, 0, n)
	b := make([]byte, 1)
	for len(out) < n {
		if _, err := rand.Read(b); err != nil {
			panic(err) // crypto/rand does not fail on supported platforms
		}
		// Only bytes below 248 (62*4) are used, so every character is equally likely.
		if b[0] < 248 {
			out = append(out, apiKeyAlphabet[int(b[0])%len(apiKeyAlphabet)])
		}
	}
	return "tly_" + string(out)
}

// HashToken returns the SHA-256 of an API key token, in hex. The store keeps this hash, never the token.
func HashToken(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

// lastFour returns the last four characters of a token.
func lastFour(token string) string {
	if len(token) < 4 {
		return token
	}
	return token[len(token)-4:]
}

func normEmail(email string) string { return strings.ToLower(strings.TrimSpace(email)) }

