	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// newAPIKeyView is the key as listed. A key that has just been created also carries its token; see createdAPIKeyView.
