package store

import (
	"encoding/json"
	"regexp"
	"strings"
	"testing"
	"time"
)

var apiKeyTokenPattern = regexp.MustCompile(`^tly_[A-Za-z0-9]{40}$`)

func validAPIKeyToken(token string) bool { return apiKeyTokenPattern.MatchString(token) }

func TestAPIKeyTokenFormat(t *testing.T) {
	s := New()
	o := newOrg(t, s, "A")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleOwner, t0)
	seen := map[string]bool{}
	for i := 0; i < 300; i++ {
		k, err := s.CreateAPIKey(o.ID, u.ID, "", t0)
		if err != nil {
			t.Fatal(err)
		}
		if !validAPIKeyToken(k.Token) || seen[k.Token] {
			t.Fatalf("token %q is malformed or repeated", k.Token)
		}
		seen[k.Token] = true
	}
}

func TestAPIKeysAreStoredHashed(t *testing.T) {
	s := New()
	o := newOrg(t, s, "A")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleOwner, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "CI", t0)

	stored, ok := s.APIKey(o.ID, k.ID)
	if !ok || stored.Token != "" || stored.TokenHash != HashToken(k.Token) || stored.Last4 != k.Token[len(k.Token)-4:] {
		t.Fatalf("stored key = %+v", stored)
	}
	if got, ok := s.APIKeyByToken(k.Token); !ok || got.ID != k.ID {
		t.Fatalf("APIKeyByToken = %+v %v", got, ok)
	}
	if _, ok := s.APIKeyByToken(k.TokenHash); ok {
		t.Fatal("the stored hash works as a token")
	}

	b, err := json.Marshal(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), k.Token) {
		t.Fatal("the export contains the plain-text token")
	}
	if !strings.Contains(string(b), k.TokenHash) {
		t.Fatal("the export does not carry the hash")
	}
}

func TestLegacyPlainTokenIsHashedOnLoad(t *testing.T) {
	const legacy = "tly_0123456789abcdefghijklmnopqrstuvwxyzABCD"
	st := State{APIKeys: []APIKey{{ID: "key_000001", OrgID: "org_000001", UserID: "usr_000001", Name: "old", Token: legacy}}}
	s, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	if got, ok := s.APIKeyByToken(legacy); !ok || got.ID != "key_000001" {
		t.Fatalf("the legacy key does not work: %+v %v", got, ok)
	}
	b, _ := json.Marshal(s.Export())
	if strings.Contains(string(b), legacy) {
		t.Fatal("the export still contains the legacy plain-text token")
	}
	got, _ := s.APIKey("org_000001", "key_000001")
	if got.Token != "" || got.TokenHash != HashToken(legacy) || got.Last4 != "ABCD" {
		t.Fatalf("key after load = %+v", got)
	}
}

func TestTouchAPIKeyWritesAtMostOncePerMinute(t *testing.T) {
	s := New()
	o := newOrg(t, s, "A")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleOwner, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "k", t0)

	s.TouchAPIKey(k.ID, t0)
	s.TouchAPIKey(k.ID, t0.Add(59*time.Second))
	if got, _ := s.APIKey(o.ID, k.ID); got.LastUsedAt == nil || !got.LastUsedAt.Equal(t0) {
		t.Fatalf("a use 59 seconds later was recorded: %v", got.LastUsedAt)
	}
	s.TouchAPIKey(k.ID, t0.Add(time.Minute))
	if got, _ := s.APIKey(o.ID, k.ID); !got.LastUsedAt.Equal(t0.Add(time.Minute)) {
		t.Fatalf("a use 60 seconds later was not recorded: %v", got.LastUsedAt)
	}
}

