package api

import (
	"net/http"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// The full token is shown only by the answer that creates the key. Listing keys shows last4 and never the token or its hash.
func TestAPIKeyTokenShownOnlyOnCreate(t *testing.T) {
	e := apitest.New(t)
	var created struct {
		ID    string `json:"id"`
		Last4 string `json:"last4"`
		Token string `json:"token"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &created)
	if !strings.HasPrefix(created.Token, "tly_") || created.Last4 != created.Token[len(created.Token)-4:] {
		t.Fatalf("created = %+v", created)
	}

	r := e.Do("GET", "/v1/api-keys", e.Acme.Key, nil)
	if r.Code != http.StatusOK {
		t.Fatalf("list: %s", r)
	}
	body := string(r.Body)
	hash := store.HashToken(created.Token)
	if strings.Contains(body, created.Token) || strings.Contains(body, hash) || strings.Contains(body, `"token"`) || strings.Contains(body, `"token_hash"`) {
		t.Fatalf("the list shows a token or its hash: %s", body)
	}
	var keys struct {
		Items []struct {
			ID     string `json:"id"`
			Last4  string `json:"last4"`
			UserID string `json:"user_id"`
		} `json:"items"`
	}
	r.JSON(t, &keys)
	found := false
	for _, k := range keys.Items {
		if k.ID == created.ID {
			found = k.Last4 == created.Last4 && k.UserID != ""
		}
	}
	if !found {
		t.Fatalf("the new key is not listed with last4 %q: %s", created.Last4, body)
	}
}

